from traitlets import HasTraits, Unicode, Bool, observe, validate
class LoginVM(HasTraits):
    user = Unicode("").tag(sync=True)
    busy = Bool(False)
    @observe("user")
    def _user_changed(self, change):
        self.can_submit = bool(change["new"].strip())
    @validate("user")
    def _check(self, proposal):
        if "\n" in proposal["value"]: raise ValueError("single line only")
        return proposal["value"]
